"""Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds.
Every line of app.log starts with YYYY-MM-DD HH:MM:SS followed by a message.
Move entries strictly older than 7 days before AS_OF to archive.log (appending,
preserving order), and rewrite app.log with the remaining entries in order.
"""

import re
import sys
from datetime import datetime, timezone, timedelta

LOG_LINE_RE = re.compile(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})")


def parse_timestamp(text: str) -> datetime | None:
    m = LOG_LINE_RE.match(text)
    if m is None:
        return None
    return datetime.strptime(m.group(1), "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp in seconds.", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 86400  # 7 days in seconds

    try:
        with open("app.log", "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("app.log not found.", file=sys.stderr)
        sys.exit(1)

    old_lines: list[str] = []
    new_lines: list[str] = []

    for line in lines:
        ts = parse_timestamp(line)
        if ts is not None and ts.timestamp() < cutoff:
            old_lines.append(line)
        else:
            new_lines.append(line)

    if old_lines:
        with open("archive.log", "a") as f:
            f.writelines(old_lines)

    with open("app.log", "w") as f:
        f.writelines(new_lines)


if __name__ == "__main__":
    main()

